"use client";

import { useId, useState } from "react";

const FAQS = [
  {
    question: "Is the land genuinely freehold and registered in my name?",
    answer:
      "Yes. Lagoon Villa Shares and Agro shares are freehold, heritable, and registered in your name on completion. Resort shares are freehold construction holdings. Full documentation is provided during your private consultation.",
  },
  {
    question: "How does the income from a Resort Share actually work?",
    answer:
      "Resort shareholders collectively receive 50% of the net profit generated by Zariya Resort operations, distributed proportionally to holdings. Income reflects year-round demand — seasonal tourism, corporate bookings, and community retreats.",
  },
  {
    question: "What does the money-back guarantee cover?",
    answer:
      "Zariya offers a 100% Money-Back Guarantee: if we cannot deliver on the commitments made to you, your investment is returned. Founding members receive additional safeguards under the Founder Protection Programme. Specific terms are detailed in your agreement.",
  },
];

/** "Questions, Answered": one answer open at a time. */
export function FaqAccordion() {
  const [open, setOpen] = useState(-1);
  const baseId = useId();

  return (
    <div data-reveal="" className="mt-[42px] flex flex-col gap-[14px]">
      {FAQS.map((faq, i) => {
        const isOpen = open === i;
        const panelId = `${baseId}-${i}`;
        return (
          <div
            key={faq.question}
            className="overflow-hidden rounded-[10px] border border-solid border-[rgba(9,44,44,.1)] bg-white"
          >
            <button
              type="button"
              onClick={() => setOpen(isOpen ? -1 : i)}
              aria-expanded={isOpen}
              aria-controls={panelId}
              className="flex w-full cursor-pointer items-center justify-between gap-5 px-[30px] py-[26px] text-left font-normal hover:bg-[rgba(9,44,44,.04)]"
            >
              <span className="text-[24.5px] text-z-green">{faq.question}</span>
              <span className="flex-shrink-0 text-[26px] leading-none text-z-deep">
                {isOpen ? "−" : "+"}
              </span>
            </button>
            {isOpen && (
              <div id={panelId} className="px-[30px] pb-7">
                <p className="text-[18px] leading-[1.85] text-[rgba(9,44,44,.88)]">{faq.answer}</p>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}
